// Extract incoming message and session ID
const body = $json.body || $json;
const messages = body.messages || [];
const sessionId = body.session_id || 'default-session';
const lastMessage = messages.length > 0 ? messages[messages.length - 1].content : (body.message || '');

// NPCI & RBI Guardrails — Never accept sensitive payment credentials
const npciRefusalRegex = /\b(otp|cvv|pin|password|full card number|expiry date)\b/i;
const promptInjectionRegex = /\b(ignore (?:previous|above) instructions|system prompt|reveal your prompt|jailbreak)\b/i;

if (npciRefusalRegex.test(lastMessage)) {
  return [{
    json: {
      blocked: true,
      reply: "For your security I can never see card numbers, CVV, PIN, or OTP. Please complete payment on the secure checkout screen.",
      sessionId,
      products: []
    }
  }];
}

if (promptInjectionRegex.test(lastMessage)) {
  return [{
    json: {
      blocked: true,
      reply: "I can't follow that instruction. Let's get back to your shopping — what groceries can I help you find?",
      sessionId,
      products: []
    }
  }];
}

return [{
  json: {
    blocked: false,
    query: lastMessage,
    sessionId,
    messages
  }
}];

return [{
  json: {
    text: .reply || 'How else can I help with your shopping?',
    products: [],
    toolCallsExecuted: ['guardrail_refusal']
  }
}];

// Format response for Razent Frontend
const agentOutput = $json.output || $json.text || 'How else can I help with your shopping?';

return [{
  json: {
    text: agentOutput,
    products: [],
    toolCallsExecuted: ['ai_agent_turn']
  }
}];
